#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, K, U;
    if (scanf("%d %d %d", &N, &K, &U) != 3) return 0;

    int *cards = malloc((size_t)N * K * sizeof(int));
    int *position = malloc((size_t)(U + 1) * sizeof(int));

    for (int i = 0; i < N * K; i++) {
        scanf("%d", &cards[i]);
    }

    for (int i = 1; i <= U; i++) {
        int number;
        scanf("%d", &number);
        position[number] = i;
    }

    int earliest = U + 1;
    int *completion = malloc((size_t)N * sizeof(int));

    for (int i = 0; i < N; i++) {
        int last = 0;
        for (int j = 0; j < K; j++) {
            int p = position[cards[i * K + j]];
            if (p > last) last = p;
        }
        completion[i] = last;
        if (last < earliest) earliest = last;
    }

    int first = 1;
    for (int i = 0; i < N; i++) {
        if (completion[i] == earliest) {
            if (!first) printf(" ");
            printf("%d", i + 1);
            first = 0;
        }
    }
    printf("\n");

    free(cards);
    free(position);
    free(completion);
    return 0;
}
